files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.breath-area {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 16px;
}

canvas {
  display: block;
  max-width: 100%;
  height: auto;
  border-radius: 50%;
  background: var(--primary);
  box-shadow: 0 0 0 4px var(--card-bg), 0 0 0 6px var(--primary);
}

.phase-label {
  margin-top: 16px;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--accent);
  min-height: 1.5em;
}

.cycle-counter {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 12px 32px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  min-width: 120px;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: scale(0.97);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover:not(:disabled) {
  background: #f05a78;
  box-shadow: 0 4px 12px rgba(233, 69, 96, 0.4);
}

.btn.secondary {
  background: var(--primary);
  color: var(--text);
}

.btn.secondary:hover:not(:disabled) {
  background: #1a4a7a;
  box-shadow: 0 4px 12px rgba(15, 52, 96, 0.4);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .btn {
    padding: 10px 24px;
    min-width: 100px;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('breathCanvas');
  const ctx = canvas.getContext('2d');
  const phaseLabel = document.getElementById('phaseLabel');
  const cycleCounter = document.getElementById('cycleCounter');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');

  const INHALE_MS = 4000;
  const EXHALE_MS = 4000;
  const CYCLE_MS = INHALE_MS + EXHALE_MS;
  const MIN_RADIUS = 40;
  const MAX_RADIUS = 130;

  let running = false;
  let rafId = null;
  let startTime = 0;
  let cycles = 0;
  let lastPhase = '';

  function draw(radius) {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    ctx.beginPath();
    ctx.arc(w / 2, h / 2, radius, 0, Math.PI * 2);
    ctx.fillStyle = '#e94560';
    ctx.fill();
  }

  function updatePhaseLabel(phase) {
    if (phase !== lastPhase) {
      lastPhase = phase;
      phaseLabel.textContent = phase;
    }
  }

  function tick(now) {
    if (!running) return;
    const elapsed = now - startTime;
    const cycleTime = elapsed % CYCLE_MS;
    let radius;
    let phase;

    if (cycleTime < INHALE_MS) {
      const t = cycleTime / INHALE_MS;
      radius = MIN_RADIUS + (MAX_RADIUS - MIN_RADIUS) * t;
      phase = 'Inhale';
    } else {
      const t = (cycleTime - INHALE_MS) / EXHALE_MS;
      radius = MAX_RADIUS - (MAX_RADIUS - MIN_RADIUS) * t;
      phase = 'Exhale';
    }

    draw(radius);
    updatePhaseLabel(phase);

    const completedCycles = Math.floor(elapsed / CYCLE_MS);
    if (completedCycles > cycles) {
      cycles = completedCycles;
      cycleCounter.textContent = 'Cycles: ' + cycles;
    }

    rafId = requestAnimationFrame(tick);
  }

  function start() {
    if (running) return;
    running = true;
    startTime = performance.now();
    cycles = 0;
    lastPhase = '';
    cycleCounter.textContent = 'Cycles: 0';
    phaseLabel.textContent = 'Inhale';
    draw(MIN_RADIUS);
    startBtn.disabled = true;
    stopBtn.disabled = false;
    rafId = requestAnimationFrame(tick);
  }

  function stop() {
    if (!running) return;
    running = false;
    if (rafId) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    startBtn.disabled = false;
    stopBtn.disabled = true;
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  draw(MIN_RADIUS);
})();
